body:
{visibleOptions.map(({ type, label }) => (
  <Button
    aria-pressed={selectedType === type}
    key={type}
    startIcon={
      selectedType === type ? <CheckIcon fontSize="small" /> : null
    }
    sx={selectedType === type ? selectedStyle : {}}
    onClick={() => onChange(type)}
    data-testid={`event-type-selector-${type}`}
  >
    {label}
  </Button>
))}

{window === SchedulingWindow.DAY && <ScheduleIcon fontSize="small" />}
{window === SchedulingWindow.WEEK && (
  <CalendarViewWeekIcon fontSize="small" />
)}
{window === SchedulingWindow.MONTH && (
  <CalendarViewMonthIcon fontSize="small" />
)}
<Typography marginLeft={0.5}>{buttonText}</Typography>

{bookingState === "booking" ? (
  <CircularProgress size={24} />
) : selectedSlot ? (
  `Book ${selectedSlot.time} on ${formatDateHeader(
    selectedSlot.date
  )}`
) : (
  "Select a slot"
)}

{/* Bold */}
<RibbonIconButton
  aria-label="Bold"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleBold().run()
    )
  }
>
  <FormatBoldIcon />
</RibbonIconButton>
{/* Italic */}
<RibbonIconButton
  aria-label="Italic"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleItalic().run()
    )
  }
>
  <FormatItalicIcon />
</RibbonIconButton>
{/* Underline */}
<RibbonIconButton
  aria-label="Underline"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleUnderline().run()
    )
  }
>
  <FormatUnderlinedIcon />
</RibbonIconButton>
{/* Strike */}
<RibbonIconButton
  aria-label="Strike"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleStrike().run()
    )
  }
>
  <FormatStrikethroughIcon />
</RibbonIconButton>

{/* Bullet List */}
<RibbonIconButton
  aria-label="Bullet List"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleBulletList().run()
    )
  }
>
  <FormatListBulletedIcon />
</RibbonIconButton>
{/* Ordered List */}
<RibbonIconButton
  aria-label="Ordered List"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleOrderedList().run()
    )
  }
>
  <FormatListNumberedIcon />
</RibbonIconButton>

        {/* Left side: name + optional chip */}

        <Typography variant="body1" noWrap>
          <Typography
            component="span"
            fontWeight={theme.typography.fontWeightBold}
            color={theme.palette.text.primary}
          >
            {patientGroup.name}
          </Typography>{" "}
          <Typography
            variant="body1"
            color={theme.palette.text.disabled}
            fontWeight="normal"
            component="span"
          >
            ({patientGroup.count} Patients)
          </Typography>
        </Typography>

        {patientGroup.preset && (
          <Chip label="Preset" size="small" sx={{ cursor: "inherit" }} />
        )}
